import { useState } from 'react'

type Props = { onCreate: (c:any)=>void }

export default function CourseForm({onCreate}:Props){
  const [title,setTitle] = useState('')
  const [skill,setSkill] = useState('Intermediate')
  const [count,setCount] = useState(5)

  function submit(e:any){
    e.preventDefault()
    const course = { id: Date.now().toString(), title, skill, count: +count }
    onCreate(course)
    setTitle('')
  }

  return (
    <form onSubmit={submit} className="card">
      <h3>Create Course</h3>
      <div>
        <label>Topic</label>
        <input value={title} onChange={e=>setTitle(e.target.value)} required />
      </div>
      <div>
        <label>Skill</label>
        <select value={skill} onChange={e=>setSkill(e.target.value)}>
          <option>Beginner</option>
          <option>Intermediate</option>
          <option>Professional</option>
        </select>
      </div>
      <div>
        <label>Number of Questions</label>
        <input type="number" value={count} onChange={e=>setCount(+e.target.value)} min={1} />
      </div>
      <div style={{marginTop:8}}>
        <button type="submit">Create Course</button>
      </div>
    </form>
  )
}
