import { useEffect, useState } from 'react'
import Link from 'next/link'
import CourseForm from '../../components/CourseForm'
import CourseList from '../../components/CourseList'

export default function CoursesPage(){
  const [courses,setCourses] = useState<any[]>([])
  useEffect(()=>{
    const raw = localStorage.getItem('am_courses')
    if(raw) setCourses(JSON.parse(raw))
  },[])

  function save(list:any[]){
    setCourses(list)
    localStorage.setItem('am_courses',JSON.stringify(list))
  }

  return (
    <div>
      <h2>Courses</h2>
      <CourseForm onCreate={(c)=> save([c,...courses])} />
      <CourseList courses={courses} onDelete={(id)=> save(courses.filter(x=>x.id!==id))} />
      <Link href="/">Home</Link>
    </div>
  )
}
