import Link from 'next/link'

export default function CourseList({courses, onDelete}:{courses:any[], onDelete:(id:string)=>void}){
  if(!courses || courses.length===0) return <div className="card">No courses yet</div>
  return (
    <div>
      {courses.map(c=> (
        <div key={c.id} className="card">
          <h4>{c.title}</h4>
          <div>Skill: {c.skill} • Questions: {c.count}</div>
          <div style={{marginTop:8}}>
            <Link href={`/courses/${c.id}`}>Start Interview</Link>
            <button style={{marginLeft:8}} onClick={()=>onDelete(c.id)}>Delete</button>
          </div>
        </div>
      ))}
    </div>
  )
}
